// ---- End of helpers ----

function isValidBST(root) {
  // check(node, low, high): every value in this subtree must be strictly between low and high.
  function check(node, low, high) {
    if (node === null) return true; // an empty tree is valid
    if (node.val <= low || node.val >= high) return false;
    // Going left, this node's value becomes the new upper bound; going right, the new lower bound.
    return check(node.left, low, node.val) && check(node.right, node.val, high);
  }
  return check(root, -Infinity, Infinity);
}
